import assert from 'node:assert/strict';
import { after, before, describe, it } from 'node:test';
import { api, startTestServer, type TestServer } from './helpers.ts';

const carriers = ['DHL', 'DPD', 'GLS', 'UPS', 'ATP'] as const;

// No ETA cache on purpose (dead end, see ledger): ETAs are computed fresh, only for the returned page.
describe('GET /shipments on a large dataset', () => {
  let srv: TestServer;

  before(async () => {
    srv = await startTestServer();
    for (let i = 0; i < 5000; i++) {
      const s = srv.store.addShipment({
        trackingNumber: `PERF${i}`,
        carrier: carriers[i % carriers.length],
        serviceLevel: 'standard',
        recipient: { name: 'A', street: 'B', zip: '1010', city: 'Wien', country: 'AT' },
      });
      srv.store.addEvent(s.id, 'picked_up');
    }
  });

  after(async () => {
    await srv.close();
  });

  it('answers the default and max page quickly with 5000 shipments', async () => {
    for (const q of ['', '?limit=500']) {
      const started = performance.now();
      const res = await api(srv.url, 'GET', `/shipments${q}`);
      const ms = performance.now() - started;
      assert.equal(res.status, 200);
      assert.equal(res.body.count, q ? 500 : 50);
      assert.ok(res.body.items.every((s: any) => typeof s.eta === 'string'));
      assert.ok(ms < 500, `list${q} took ${Math.round(ms)} ms`);
    }
  });

  it('shows an updated ETA right after a new exception event', async () => {
    const before = (await api(srv.url, 'GET', '/shipments?limit=1')).body.items[0];
    srv.store.addEvent(before.id, 'exception');
    const after = (await api(srv.url, 'GET', '/shipments?limit=1')).body.items[0];
    assert.equal(after.id, before.id);
    assert.ok(after.eta > before.eta, `${after.eta} should be later than ${before.eta}`);
  });
});
EOF
